// 3D model of the right pterygopalatine fossa from Z-Anatomy meshes (CC BY-SA
// 4.0, based on BodyParts3D): the maxilla, palatine bone, sphenoid and nasal
// cavity, the maxillary nerve and the third part of the maxillary artery with
// its branches. The pterygopalatine ganglion and its nerves (Vidian, palatine,
// nasopalatine, posterior superior alveolar, zygomatic and pharyngeal) are
// drawn for this app. Geometry and the traced courses live in
// data/pterygopalatine-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred on the fossa: +y = superior,
// +z = anterior, the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.pterygopalatine = {
  // Default view: the right side, from slightly in front and below.
  camera: { target: [0, 0, 0.2], radius: 20, theta: -1.2, phi: 1.68 },

  // [theta, phi] for the view buttons. The right side faces -x; "Medial" looks
  // from the nasal cavity side (from the left) with the septum removed.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-0.6, 2.6],
    anterior: [Math.PI / 2, Math.PI / 2]
  },
  viewLabels: { anterior: "Medial" },

  // Starting axial level (0 = bottom of the model, 1 = top): through the fossa.
  sectionLevel: 0.5,

  look: {
    maxilla: { kind: "bone", opacity: 0.55 },
    palatine: { kind: "bone", color: 0xe3d2ae, opacity: 0.8 },
    sphenoid: { kind: "bone", color: 0xe6d6b4, opacity: 0.7 },
    vomer: { kind: "bone", opacity: 0.6 },
    ethmoid_conchae: { kind: "bone", opacity: 0.45 },
    zygomatic: { kind: "bone", opacity: 0.6 },
    nasal_mucosa: { kind: "gland", color: 0xe0a4a0, opacity: 0.22 },
    auditory_tube: { kind: "cartilage", color: 0xc9b6c8, opacity: 0.7 },
    pterygoids: { kind: "muscle", color: 0x9a3c3c, opacity: 0.6 },
    trigeminal: { kind: "nerve", color: 0xf2c94c },
    v2: { kind: "nerve", color: 0xf2c94c },
    ppg: { kind: "nerve", color: 0xe8a93a },
    ganglionic_branches: { kind: "nerve" },
    vidian: { kind: "nerve", color: 0xf0d27a },
    greater_palatine_n: { kind: "nerve" },
    nasopalatine: { kind: "nerve" },
    psa_nerve: { kind: "nerve" },
    zygomatic_nerve: { kind: "nerve" },
    pharyngeal_nerve: { kind: "nerve" },
    maxillary_artery: { kind: "artery" },
    infraorbital_artery: { kind: "artery" },
    psa: { kind: "artery" },
    descending_palatine: { kind: "artery" },
    sphenopalatine: { kind: "artery" },
    pterygoid_canal_artery: { kind: "artery" },
    ica: { kind: "artery" }
  },

  build(THREE, h) {
    return h.fromMeshes("pterygopalatine", this.look);
  }
};
